      "tag": "BRAND_IMPERSONATION"
    },
    {
      "code": "cktelefoonopstellenconfiguraties.nl",
      "code_explain": "Obfuscated/lookalike Dutch domain ('phone setup configurations') with no relation to any recognizable service. Newly registered or low-reputation domains hosting login pages are a strong phishing indicator.",
      "tag": "CREDENTIAL_HARVESTING"
    },
    {
      "code": "<img src=https://www.vocalwire.com/images/ajax_loader.gif> (ajax loader used to mask redirect delay)",
