      "tag": "SOCIAL_ENGINEERING"
    },
    {
      "code": "No From: header, no sender identity, no branding, no subject, no recipient address",
      "code_explain": "Complete absence of sender identification or verifiable branding is inconsistent with legitimate operational or customer-support email.",
      "tag": "SOCIAL_ENGINEERING"
    }
  ],
  "explain": "The message has no sender, uses a meta-refresh to silently redirect to an unbranded Dutch login page, and pairs the redirect with reassurance text to push the recipient into entering credentials. These are textbook credential-harvesting phishing indicators, so the verdict is Phishing.",
  "is_phishing": "Phishing",
  "tag": "CREDENTIAL_HARVESTING"
}

