      "code": "var a=toNumbers(\"f655ba9d09a112d4968c63579db590b4\"),b=toNumbers(\"98344c2eee86c3994890592585b49f80\"),c=toNumbers(\"97f2bc6b714dcd60abdff0cba3897cf0\");",
      "code_explain": "Hardcoded AES key/IV/ciphertext blobs are used to dynamically produce a cookie value, a classic obfuscation/deobfuscation trick to evade static URL inspection.",
      "tag": "MALWARE_DELIVERY"
    },
    {
      "code": "document.cookie=\"__test=\"+toHex(slowAES.decrypt(c,2,a,b))+\"; expires=Thu, 31-Dec-37 23:55:55 GMT; path=/\"",
      "code_explain": "Sets a persistent cookie (expires year 2037) derived from decrypted ciphertext, a tracking/fingerprinting mechanism often used in phishing kits.",
      "tag": "MALWARE_DELIVERY"
    },
    {
      "code": "location.href=\"http://seguridpromeri34.byethost24.com/pase.php?i=1\"",
      "code_explain": "Forces client-side redirect to a free-hosting (byethost24.com) lookalike domain ('seguridpromeri34') serving 'pase.php' (Spanish for 'pass' / 'step'), typical of credential-harvesting or malware landing pages.",
