    {
      "code": "seguridpromeri34.byethost24.com",
      "code_explain": "Lookalike impersonation of a security-related name hosted on a free web host frequently abused for phishing and malware delivery.",
      "tag": "BRAND_IMPERSONATION"
    },
    {
      "code": "<noscript>This site requires Javascript to work, please enable Javascript in your browser or use a browser with Javascript support</noscript>",
      "code_explain": "Social-engineering nudge to enable JavaScript so the malicious redirect executes, a common phishing/malware technique.",
      "tag": "SOCIAL_ENGINEERING"
    }
  ],
