    },
    {
      "code": "var hea2p = ('0123456789ABCDEFGHIJKLMNOPQRSTUVXYZabcdefghijklmnopqrstuvxyz');",
      "code_explain": "Defines the decryption key/pass alphabet inline; legitimate emails do not contain client-side cryptographic routines.",
      "tag": "MALWARE_DELIVERY"
