    },
    {
      "code": "<input ... id=usernameId ... name=username ng-model=$ctrl.method.username.value required xid=username> ... <button class=\"login-button i-button ...\" name=\"sendSMS \" ... ng-click=$ctrl.handleInitialize()>Poslat kód</button>",
      "code_explain": "Form requests the client identifier ('Klientské číslo') and triggers an SMS authentication code request ('Poslat kód'), a classic two-step credential/MFA harvesting pattern used against banking users.",
